import csv
import json
import os
from decimal import Decimal
from pathlib import Path

path = Path(os.environ["CONSUMER_FLOW_DIR"]) / "20190917_consumer.csv"
rows = []
with path.open("r", encoding="utf-8-sig", newline="") as f:
    for row in csv.DictReader(f):
        if row["用户"] == "上海管网":
            rows.append({
                "供气点": row["供气点"],
                "消耗量": Decimal(row["消耗量"]),
            })

by_point = {}
for row in rows:
    by_point[row["供气点"]] = by_point.get(row["供气点"], Decimal("0")) + row["消耗量"]

result = {
    "用户": "上海管网",
    "总消耗量": str(sum((row["消耗量"] for row in rows), Decimal("0"))),
    "供气点数": len(by_point),
    "供气点_按消耗量降序": [
        {"供气点": name, "消耗量": str(value)}
        for name, value in sorted(by_point.items(), key=lambda x: (-x[1], x[0]))
    ],
}
print(json.dumps(result, ensure_ascii=False))

